        {
            "openapi": "3.1.0",
            "info": {"title": "FastAPI", "version": "0.1.0"},
            "paths": {
                "/with-duplicates": {
                    "post": {
                        "summary": "With Duplicates",
                        "operationId": "with_duplicates_with_duplicates_post",
                        "requestBody": {
                            "content": {
                                "application/json": {
                                    "schema": {"$ref": "#/components/schemas/Item"}
